'use strict';
// Public anonymous full-body verification only. No release mutation or credentials.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const manifestPath=path.join(__dirname,'manifest.json'),bytes=fs.readFileSync(manifestPath),manifest=JSON.parse(bytes),sha=value=>crypto.createHash('sha256').update(value).digest('hex');
async function main(){assert.equal(process.env.GH_TOKEN||'','');assert.equal(process.env.GITHUB_TOKEN||'','');assert.equal(process.env.GITHUB_EVENT_NAME,'workflow_dispatch');assert.equal(manifest.version,'0.4.23');assert.equal(manifest.buildId,'20261016.6');assert.equal(manifest.sourceHash,'077145ac68b90a78790b9f6a875d6efb374cfce2682f002c4107afe54fe1dafa');assert.equal(manifest.artifacts.length,3);
 const startedAt=new Date().toISOString();const publicArtifacts=await Promise.all(manifest.artifacts.map(async artifact=>{const url=new URL(artifact.url);assert.equal(url.origin,'https://github.com');assert(url.pathname.startsWith('/unmet23-lab/synk-policy/releases/download/'+manifest.releaseId+'/'));assert.match(artifact.sha256,/^[0-9a-f]{64}$/);assert(Number.isSafeInteger(artifact.bytes)&&artifact.bytes>0);const begin=Date.now();const response=await fetch(artifact.url,{method:'GET',credentials:'omit',redirect:'follow',signal:AbortSignal.timeout(360000)});assert.equal(response.status,200);const finalURL=new URL(response.url);assert.equal(finalURL.protocol,'https:');assert(finalURL.hostname.endsWith('.githubusercontent.com'));const hash=crypto.createHash('sha256');let received=0;assert(response.body);for await(const chunk of response.body){received+=chunk.byteLength;assert(received<=artifact.bytes,'Public response exceeds pinned bytes');hash.update(chunk);}const digest=hash.digest('hex');assert.equal(received,artifact.bytes);assert.equal(digest,artifact.sha256);const result={url:artifact.url,bytes:received,sha256:digest,status:response.status,method:'GET',anonymous:true,authorizationHeader:false,cookieHeader:false,credentials:'omit',fullBodyRead:true,redirectOrigin:finalURL.origin,elapsedMs:Date.now()-begin};console.log(JSON.stringify({verified:artifact.platform+'-'+artifact.arch,bytes:received,sha256:digest,anonymousFullGET:true}));return result;}));
 const result={ok:true,startedAt,completedAt:new Date().toISOString(),manifestSHA256:sha(bytes),manifestBytes:bytes.length,version:manifest.version,buildId:manifest.buildId,releaseId:manifest.releaseId,sourceHash:manifest.sourceHash,scriptSHA256:sha(fs.readFileSync(__filename)),run:{id:process.env.GITHUB_RUN_ID,attempt:process.env.GITHUB_RUN_ATTEMPT,head:process.env.GITHUB_SHA,ref:process.env.GITHUB_REF,workflow:process.env.GITHUB_WORKFLOW,job:process.env.GITHUB_JOB,repository:process.env.GITHUB_REPOSITORY,event:process.env.GITHUB_EVENT_NAME},publicArtifacts,anonymousFullGET:true,remoteMutations:0,assetChanges:0,secretsRecorded:false};const output=path.resolve('public-artifact-verification');fs.mkdirSync(output);fs.writeFileSync(path.join(output,'report.json'),JSON.stringify(result,null,2)+'\n',{flag:'wx'});}
main().catch(error=>{console.error(error.name+': '+error.message);process.exitCode=1;});
